"""Reusable owner-only personal details, encrypted with the native vault engine.

The model sees availability, never contact/address values. The hosted owner UI
can edit values; the browser handler resolves them only for the requested origin.
Personal details are not credential invitations or conversational memory.
"""
import json
import re
import secrets
from contextlib import ExitStack
from urllib.parse import urlsplit

from agent.vault_store import VaultStore, ADDRESS_FIELDS, normalize_origin
from agent.vault_login_classifier import (
    LoginControl, classify_checkout_control, build_inspection_js, build_fill_js, _RE_OTP,
)
from .login import normalize_phone, normalize_controls, phone_fills
from .store import AccessError

KINDS = ('email', 'phone', 'address')
LABELS = {'email': 'Primary email', 'phone': 'Primary phone', 'address': 'Primary address'}


def validate(kind, fields):
    if kind not in KINDS or not isinstance(fields, dict):
        raise AccessError('Choose email, phone or address.')
    allowed = {'email'} if kind == 'email' else {'phone_number', 'country_code'} if kind == 'phone' else set(ADDRESS_FIELDS)
    if set(fields) - allowed or any(not isinstance(value, str) for value in fields.values()):
        raise AccessError('Use only the personal details shown in this form.')
    values = {key: value.strip() for key, value in fields.items() if value.strip()}
    if any(len(value) > 500 or re.search(r'[\x00-\x1f\x7f]', value) for value in values.values()):
        raise AccessError('Enter valid personal details using one line per field.')
    if kind == 'email':
        email = values.get('email', '')
        if len(email) > 254 or not re.fullmatch(r'[^\s@]+@[^\s@]+\.[^\s@]+', email):
            raise AccessError('Enter a valid email address.')
        return {'email': email}
    if kind == 'phone':
        phone = normalize_phone(values.get('phone_number', ''))
        if not phone.startswith('+'):
            raise AccessError('Include the country code, for example +91 or +1.')
        code = values.get('country_code', '')
        if code and (not re.fullmatch(r'\+[1-9][0-9]{0,2}', code) or not phone.startswith(code) or len(phone) - len(code) < 7):
            raise AccessError('The country code must match the start of your phone number.')
        return {'phone_number': phone, **({'country_code': code} if code else {})}
    if any(not values.get(key) for key in ('address_line1', 'city', 'postal_code', 'country')):
        raise AccessError('Enter your street address, city, postal code and country.')
    return values


class PersonalStore(VaultStore):
    """Separate encrypted records; normal credential listings never include them."""
    def __init__(self, home):
        super().__init__(home / 'vault')
        self._vault_path = self._base / 'personal.json.enc'

    def values(self, kind):
        if kind not in KINDS:
            raise AccessError('Choose email, phone or address.')
        with self._locked():
            record = next((item for item in self._read_all() if item.get('id') == kind), None)
            return dict(record['secret']) if record and record.get('secret') else None

    def save(self, kind, fields):
        values = validate(kind, fields)
        with self._locked():
            items = [item for item in self._read_all() if item.get('id') != kind]
            self._write_all(items + [{'id': kind, 'secret': values}])

    def remove(self, kind):
        if kind not in KINDS:
            raise AccessError('Choose email, phone or address.')
        with self._locked():
            # Keep an encrypted opt-out so later website saves cannot silently
            # restore a primary detail the owner deliberately removed.
            items = [item for item in self._read_all() if item.get('id') != kind]
            self._write_all(items + [{'id': kind, 'secret': None}])

    def remember(self, kind, fields):
        """Keep the first valid contact, preserving overrides and removal."""
        try:
            values = validate(kind, fields)
        except AccessError:
            # A website may accept a national number or a username. Neither
            # gives us enough information to invent a cross-site default.
            return False
        with self._locked():
            items = self._read_all()
            if any(item.get('id') == kind for item in items):return False
            self._write_all(items + [{'id': kind, 'secret': values}])
            return True

    def remember_login(self, vault, meta):
        """Resolve only a successfully saved login in this owner's vault."""
        if vault._base.resolve() != self._base.resolve():
            raise AccessError('Personal details must come from your own saved login.', 403)
        if meta.kind != 'login':return False
        if meta.login_method == 'sms':
            return self.remember('phone', {'phone_number': vault.resolve_secret(meta.id)['phone_number']})
        if meta.identifier_type == 'email':
            return self.remember('email', {'email': meta.identifier})
        return False

    def summary(self):
        result = {}
        for kind in KINDS:
            values = self.values(kind)
            summary = ''
            if values and kind == 'phone':summary = 'Ending ' + values['phone_number'][-4:]
            if values and kind == 'email':summary = values['email'][0] + '•••@' + values['email'].split('@')[1]
            if values and kind == 'address':summary = 'Saved for delivery and forms'
            result[kind] = {'saved': values is not None, 'label': LABELS[kind], 'summary': summary}
        return result


def personal_fills(controls, values, fields, *, phone_context=None):
    """Choose unambiguous visible fields; never overwrite another person's data."""
    controls = normalize_controls(controls)
    fills = []
    if 'phone' in fields:
        phone = values['phone']['phone_number']
        # Select the field before checking length, so an explicit nearby calling
        # code can identify a national field without asking for the number again.
        candidates = phone_fills(controls, '')
        target = next(c for c in controls if c.index == candidates[0]['index'])
        code = values['phone'].get('country_code')
        observed = (phone_context or {}).get(str(target.index))
        use_national = (code and ('tel-national' in target.autocomplete.split() or observed == code))
        if not code and isinstance(observed, str) and re.fullmatch(r'\+[1-9][0-9]{0,2}', observed) and phone.startswith(observed) and len(phone) - len(observed) >= 7:
            code, use_national = observed, True
        number = phone[len(code):] if use_national else phone
        if target.max_length is not None and len(number) > target.max_length:
            raise AccessError('Inspect the website\'s phone format and country code before retrying this saved number.', 409)
        candidates[0]['value'] = number
        fills += candidates
    if 'email' in fields:
        candidates = []
        for control in controls:
            if control.type not in ('email', 'text', '') or 'one-time-code' in control.autocomplete or _RE_OTP.search(control.name+' '+control.label):
                continue
            score = 100 if 'email' in control.autocomplete.split() or control.type == 'email' else 70 if 'username' in control.autocomplete.split() or re.search(r'\b(email|e mail)\b', control.name + ' ' + control.label, re.I) else 0
            if score:candidates.append((score, control))
        if not candidates:
            raise AccessError('Open the email field before filling your primary email.', 409)
        best = [c for score, c in candidates if score == max(item[0] for item in candidates)]
        if len(best) != 1:raise AccessError('The email field is ambiguous. Leave only the intended form open.', 409)
        fills.append({'index': best[0].index, 'token': 'email', 'value': values['email']['email']})
    if 'address' in fields:
        classified = [c for control in controls if (c := classify_checkout_control(control)) and c.token in ADDRESS_FIELDS.values()]
        for key, token in ADDRESS_FIELDS.items():
            value = values['address'].get(key)
            candidates = [c for c in classified if c.token == token]
            if not value or not candidates:continue
            best = [c for c in candidates if c.score == max(item.score for item in candidates)]
            if len(best) != 1:raise AccessError('The address fields are ambiguous. Leave only the intended form open.', 409)
            fills.append({'index': best[0].control.index, 'token': token, 'value': value})
        if not any(fill['token'] in ADDRESS_FIELDS.values() for fill in fills):
            raise AccessError('Open the delivery address form before filling your primary address.', 409)
    lengths = {c.index: c.max_length for c in controls}
    if len({f['index'] for f in fills}) != len(fills) or any(lengths[f['index']] is not None and len(f['value']) > lengths[f['index']] for f in fills):
        raise AccessError('The saved details do not fit the visible form. Review this website privately.', 409)
    return fills


def exact_origin(origin):
    if not isinstance(origin, str):raise AccessError('Choose the exact HTTPS website origin.')
    parsed = urlsplit(origin)
    if (parsed.scheme != 'https' or not parsed.hostname or parsed.username or parsed.password or
            parsed.path not in ('', '/') or parsed.query or parsed.fragment):
        raise AccessError('Choose the exact HTTPS website origin, with no path or embedded credentials.')
    return normalize_origin(origin)


class PersonalInfo:
    def __init__(self, service):self.service = service

    def store(self, team, owner):return PersonalStore(self.service.private_home(team, owner))

    def register_redactions(self, turn):
        from agent.redact import register_vault_redaction_value
        store = self.store(turn.source.scope_id, turn.source.user_id)
        for kind in KINDS:
            values = store.values(kind) or {}
            for key, value in values.items():
                # Geographic names also occur in public routes and brands.
                # Street/unit/postal details remain protected independently.
                if key not in ('country_code','city','state','country'):
                    register_vault_redaction_value(value)
            if kind == 'phone' and values:
                number = values['phone_number']
                register_vault_redaction_value(number.lstrip('+'))
                if values.get('country_code'):register_vault_redaction_value(number[len(values['country_code']):])

    def fill(self, turn, *, origin, fields):
        service = self.service
        home = service.assert_private(turn)
        service.delegations.check_execution(turn)
        origin = exact_origin(origin)
        if (not isinstance(fields, list) or not fields or any(not isinstance(field, str) for field in fields) or len(set(fields)) != len(fields) or
                any(field not in KINDS for field in fields)):
            raise AccessError('Choose only phone, email or address to fill.')
        owner_home = service.private_home(turn.source.scope_id, turn.source.user_id)
        with ExitStack() as locks:
            locks.enter_context(service.lock_for(home))
            if owner_home != home:locks.enter_context(service.lock_for(owner_home))
            store = self.store(turn.source.scope_id, turn.source.user_id)
            values = {kind: store.values(kind) for kind in fields}
            # A stored site's identifier is the override for that account. New
            # sites use primary defaults. More than one saved account needs a
            # deliberate handle selection rather than replacing its identifier.
            vault = VaultStore(owner_home / 'vault')
            logins = [meta for meta in vault.list_items() if meta.kind == 'login' and meta.origin == origin]
            if len(logins) > 1 and any(kind in fields for kind in ('phone', 'email')):
                raise AccessError('This website has multiple saved accounts. Choose its login handle first.', 409)
            if logins and 'email' in fields and logins[0].identifier_type == 'email':
                values['email'] = {'email': logins[0].identifier}
            if logins and 'phone' in fields and logins[0].login_method == 'sms':
                number = vault.resolve_secret(logins[0].id)['phone_number']
                if not values['phone'] or number != values['phone']['phone_number']:
                    values['phone'] = {'phone_number': number}
            if any(value is None for value in values.values()):
                return {'status': 'personal_info_needed', 'missing': [kind for kind, value in values.items() if value is None],
                        'available_fields': [kind for kind, value in values.items() if value is not None],
                        'vault_url': service.config['public_url'].rstrip('/') + '/vault',
                        'next': 'Fill available_fields separately in this task\'s private browser. Ask only for missing required fields through Personal info in the private vault, then resume. Never ask for saved details again or collect private values in chat.'}
            from tools import browser_vault_tool as native
            from .browser_context import authorize_supervisor, browser_task_id, remember_redactions
            native_task_id = browser_task_id(turn)
            supervisor = native._ensure_supervisor(native_task_id)
            if supervisor is None:
                raise AccessError('Open this task\'s private browser before filling personal details.', 409)
            authorize_supervisor(turn, supervisor)
            if not supervisor.focus_page(origin).get('ok') or native._current_page_origin(native_task_id) != origin:
                raise AccessError('The open form does not match the requested website.', 403)
            nonce = secrets.token_hex(8)
            inspection = build_inspection_js(nonce).replace('input, select', 'input, select, textarea')
            raw = native._eval_js(native_task_id, inspection)
            controls = native._parse_json_result(raw.get('result')) if raw.get('success') else None
            if isinstance(controls, str):controls = native._parse_json_result(controls)
            if not isinstance(controls, list):raise AccessError('The personal details form could not be inspected.', 409)
            context = supervisor.evaluate_runtime(r'''(() => {const result={}; for(const el of document.querySelectorAll('[data-hermes-vault-slot]')) {const slot=el.getAttribute('data-hermes-vault-slot').split(':').pop(); const parent=el.parentElement; const text=parent?.innerText||''; const select=parent?.querySelector('select'); const selected=select?.selectedOptions?.[0]?.textContent||''; const codes=(text.length<240?text+' '+selected:selected).match(/\+[1-9][0-9]{0,2}(?![0-9])/g)||[]; if(new Set(codes).size===1)result[slot]=codes[0];}return result;})()''')
            fills = personal_fills([LoginControl.from_dict(c) for c in controls], values, fields,
                                   phone_context=context.get('result') if context.get('ok') else None)
            from agent.redact import register_vault_redaction_value
            self.register_redactions(turn)
            for fill in fills:
                if fill['token'] not in ('address-level2','address-level1','country-name'):
                    register_vault_redaction_value(fill['value'])
            script = build_fill_js(fills, expected_origin=origin, nonce=nonce).replace(
                'HTMLInputElement.prototype', "(el.tagName==='TEXTAREA'?HTMLTextAreaElement:HTMLInputElement).prototype")
            remember_redactions(turn, [fill['value'] for fill in fills
                                      if fill['token'] not in ('address-level2','address-level1','country-name')])
            result = native._eval_js_secret(native_task_id, script)
            data = native._parse_json_result(result.get('result')) if result.get('success') else None
            if isinstance(data, str):data = native._parse_json_result(data)
            if not isinstance(data, dict) or data.get('refused') or data.get('filled') != len(fills):
                raise AccessError('The personal details fill was not fully confirmed. Review the form before continuing.', 409)
            return {'success': True, 'filled_fields': len(fills), 'origin': origin,
                    'next': 'The requested personal details are filled. Review the form and continue the user\'s task; no form has been submitted.'}

