async def test_identity_http_crud_is_encrypted_owner_private_and_metadata_only(service):
    http = TestClient(TestServer(VaultWeb(service, service.config).app))
    await http.start_server()
    try:
        headers = {}
        for owner in ('UA', 'UB'):
            sid = service.store.new_session('TT', owner)
            headers[owner] = {'Origin': 'https://vault.example',
                              'Cookie': '__Host-clanker=' + sid,
                              'X-CSRF-Token': service.store.session(sid)['csrf']}
        private_values = [value for fields in IDENTITY.values() for value in fields.values()]
        for kind, fields in IDENTITY.items():
            response = await http.post('/api/personal/save', json={'kind': kind, 'fields': fields},
                                       headers=headers['UA'])
            result = await response.json()
            assert response.status == 200, result
            assert result['personal_info'][kind]['saved']
            assert all(value not in json.dumps(result) for value in private_values)
            store = PersonalStore(service.private_home('TT', 'UA'))
            assert store.values(kind) == fields
            assert (store._vault_path.stat().st_mode & 0o777) == 0o600
            for path in (store._vault_path, service.store.path):
                assert all(value.encode() not in path.read_bytes() for value in private_values)
            assert VaultStore(service.private_home('TT', 'UA') / 'vault').list_items() == []
            response = await http.post('/api/personal/details', json={'kind': kind}, headers=headers['UA'])
            assert (await response.json())['fields'] == fields
            response = await http.post('/api/personal/details', json={'kind': kind}, headers=headers['UB'])
            assert (await response.json())['fields'] == {}
            for endpoint, payload in (
                ('/api/personal/details', {'kind': kind}),
                ('/api/personal/remove', {'kind': kind}),
                ('/api/personal/save', {'kind': kind, 'fields': fields}),
            ):
                response = await http.post(endpoint, json=payload,
                                           headers=headers['UA'] | {'X-CSRF-Token': 'bad'})
                assert response.status == 403
                response = await http.post(endpoint, json=payload | {'owner': 'UB'}, headers=headers['UA'])
                assert response.status == 400
                response = await http.post(endpoint, json=payload,
                                           headers=headers['UA'] | {'Origin': 'https://evil.invalid'})
                assert response.status == 403
                response = await http.post(endpoint, json=payload, headers={'Origin': 'https://vault.example'})
                assert response.status == 401
        response = await http.post('/api/items', json={}, headers=headers['UA'])
        result = await response.json()
        assert all(result['personal_info'][kind]['saved'] for kind in IDENTITY)
        assert all(value not in json.dumps(result) for value in private_values)
        changed = {'given_name': 'Morgan', 'family_name': 'Hayes'}
        response = await http.post('/api/personal/save', json={'kind': 'name', 'fields': changed}, headers=headers['UA'])
        assert response.status == 200
        assert PersonalStore(service.private_home('TT', 'UA')).values('name') == changed
        for kind in IDENTITY:
            response = await http.post('/api/personal/remove', json={'kind': kind}, headers=headers['UA'])
            assert response.status == 200
            assert not (await response.json())['personal_info'][kind]['saved']
            assert PersonalStore(service.private_home('TT', 'UA')).values(kind) is None
            assert PersonalStore(service.private_home('TT', 'UB')).values(kind) is None
    finally:
        await http.close()


