    monkeypatch.setattr(browser_tool, '_cached_agent_browser', None)
    monkeypatch.setattr(browser_tool, '_agent_browser_resolved', False)
    monkeypatch.setattr(SUPERVISOR_REGISTRY, '_by_task', {})
    monkeypatch.setattr(KernelBrowser, 'driver', lambda self, turn: '/fixture/agent-browser')
    def attach(task_id):
        current = browser_tool._active_sessions[task_id]
        SUPERVISOR_REGISTRY._by_task[task_id] = Supervisor(task_id, current['cdp_url'])
    monkeypatch.setattr('tools.browser_tool_cdp._ensure_cdp_supervisor', attach)
    monkeypatch.setattr('gateway.slack_workspace.workspace_policy', lambda *args: service.policy)
    yield SimpleNamespace(cloud=cloud, client=client, service=service, turns=turns,
