    for turn in turns.values():
        with _profile_runtime_scope(turn.home):
            clear_vault_redaction_values()


def prepare(kernel, owner):
    turn = kernel.turns[owner]
    with scope(turn):
        return kernel.cloud.prepare(turn)


def entry(kernel, owner):
    return next(iter(kernel.cloud.state(kernel.turns[owner])[1]['sessions'].values()))


def saved(kernel, owner='UA', *, password='REDACTED', otp_secret=None):
    value = {'identifier': owner.lower() + '@example.invalid',
             'identifier_type': 'email', 'password': password}
    if otp_secret:
        value['otp_secret'] = otp_secret
    return VaultStore(kernel.turns[owner].home / 'vault').add_item(
        'login', 'Fixture account', value, origin='https://accounts.example.com')


def test_a_b_a_reattaches_only_own_remote_browser_and_native_state(kernel):
    a = prepare(kernel, 'UA')
    b = prepare(kernel, 'UB')
    again = prepare(kernel, 'UA')
    assert a['bb_session_id'] == again['bb_session_id'] != b['bb_session_id']
    assert len(kernel.client.creates) == 2
    for owner, current in (('UA', again), ('UB', b)):
        turn = kernel.turns[owner]
        assert kernel.native._active_sessions[kernel.cloud.native_task_id(turn)]['bb_session_id'] == current['bb_session_id']
        assert kernel.native._session_owner_homes[kernel.cloud.native_task_id(turn)] == str(turn.home)
        with scope(turn):
            kernel.cloud.assert_supervisor(turn, kernel.registry.get(kernel.cloud.native_task_id(turn)))


def test_shared_logical_task_id_has_separate_requester_browsers_and_fills(kernel):
    from vault.tools import execute
    for turn in kernel.turns.values():
        turn.task_id = 'shared-slack-thread-task'
    handles = {owner: saved(kernel, owner, password='private-password-' + owner)
               for owner in ('UA', 'UB')}
    a = prepare(kernel, 'UA')
    b = prepare(kernel, 'UB')
    assert a['session_key'] != b['session_key']
    assert a['owner_task_id'] == a['session_key'] and b['owner_task_id'] == b['session_key']
    assert 'shared-slack-thread-task' not in kernel.native._active_sessions
    for owner in ('UA', 'UB', 'UA'):
        current = prepare(kernel, owner)
        turn = kernel.turns[owner]
        supervisor = kernel.registry.get(current['session_key'])
        with scope(turn):
            result = json.loads(execute('clanker_vault_fill',
                {'handle': handles[owner].id}, task_id=turn.task_id))
        assert result['success'] and supervisor.fills[-1]['value'] == 'private-password-' + owner
        assert current['bb_session_id'] == (a if owner == 'UA' else b)['bb_session_id']

